// Generated by Cypress Author on 2026-10-19
//
// USU 08 · USU 09 · USU 10 (P0/P1) — Plano_de_Testes_QA_MatchWallet.md §4.
// Só a camada de UI: a autorização e a regra do último administrador vivem no servidor
// (ver e2e/real/autorizacao.cy.ts). Aqui o 409 `ULTIMO_ADMIN` é stubado para provar que a tela
// mostra a mensagem da API e não altera o estado exibido.

const CLIENTE = {
  id: 'c0000000-0000-4000-8000-000000000001',
  nome: 'Ana Cliente',
  email: 'ana@teste.com',
  perfil: 'cliente',
  ativo: true,
  criadoEm: '2026-01-10T00:00:00.000Z',
}

const ADMIN = {
  id: 'a0000000-0000-4000-8000-000000000001',
  nome: 'Admin Unico',
  email: 'admin.unico@teste.com',
  perfil: 'admin',
  ativo: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
}

function abrirUsuario(nome: string) {
  cy.contains('[data-cy="usuario-linha"]', nome).click()
}

describe('Plano QA · Usuários administrativos', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('admin')
    cy.stubApi(
      'GET',
      '/usuarios*',
      { items: [CLIENTE, ADMIN], total: 2, page: 1, pageSize: 100 },
      'usuarios',
    )
    cy.stubApi('GET', '/usuarios/*/historico-suitability', [], 'historico')
    cy.visit('/admin/usuarios')
    cy.wait('@usuarios')
  })

  it('USU 08 · admin troca o papel de Cliente para Admin → envia PATCH { perfil } e confirma a alteração', () => {
    cy.stubApi('PATCH', '/usuarios/*', { ...CLIENTE, perfil: 'admin' }, 'atualizar')

    abrirUsuario(CLIENTE.nome)
    // Sem mudança o botão Salvar fica travado.
    cy.get('[data-cy="usuario-papel-salvar"]').should('be.disabled')

    cy.get('#usuario-papel').click()
    cy.contains('[role="option"]', 'Admin').click()
    cy.get('[data-cy="usuario-papel-salvar"]').should('be.enabled').click()

    cy.wait('@atualizar').then(({ request }) => {
      expect(request.url).to.contain(`/usuarios/${CLIENTE.id}`)
      expect(request.body).to.deep.equal({ perfil: 'admin' })
    })
    cy.contains('Papel atualizado').should('be.visible')
  })

  it('USU 09 · API recusa retirar o papel do último admin (409) → mostra a mensagem e mantém o papel Admin', () => {
    const mensagem = 'Não é possível remover o último administrador ativo.'
    cy.stubErroApi(
      'PATCH',
      '/usuarios/*',
      { status: 409, code: 'ULTIMO_ADMIN', message: mensagem },
      'atualizar',
    )

    abrirUsuario(ADMIN.nome)
    cy.get('#usuario-papel').click()
    cy.contains('[role="option"]', 'Cliente').click()
    cy.get('[data-cy="usuario-papel-salvar"]').click()

    cy.wait('@atualizar').its('response.statusCode').should('eq', 409)
    cy.contains(mensagem).should('be.visible')
    cy.contains('Papel atualizado').should('not.exist')
    // O controle volta ao papel real, sem fingir que a troca aconteceu.
    cy.get('#usuario-papel').should('contain.text', 'Admin')
  })

  it('USU 09 · API recusa inativar o último admin (409) → mostra a mensagem e o usuário continua ativo', () => {
    const mensagem = 'Não é possível inativar o último administrador ativo.'
    cy.stubErroApi(
      'PATCH',
      '/usuarios/*',
      { status: 409, code: 'ULTIMO_ADMIN', message: mensagem },
      'atualizar',
    )

    abrirUsuario(ADMIN.nome)
    cy.get('[data-cy="usuario-inativar"]').click()
    cy.get('[data-slot="confirm-dialog"]').contains('button', 'Inativar usuário').click()

    cy.wait('@atualizar').its('request.body').should('deep.equal', { ativo: false })
    cy.contains(mensagem).should('be.visible')
    cy.contains('Usuário inativado').should('not.exist')
    cy.get('[data-cy="usuario-inativar"]').should('be.visible')
  })

  it('USU 10 · admin cancela a inativação e depois confirma → só a confirmação chama a API', () => {
    cy.stubApi('PATCH', '/usuarios/*', { ...CLIENTE, ativo: false }, 'atualizar')

    abrirUsuario(CLIENTE.nome)
    cy.get('[data-cy="usuario-inativar"]').click()
    cy.get('[data-slot="confirm-dialog"]').contains('Inativar este usuário?').should('be.visible')
    cy.get('[data-slot="confirm-dialog"]').contains('button', 'Manter ativo').click()
    cy.get('[data-slot="confirm-dialog"]').should('not.exist')
    cy.get('@atualizar.all').should('have.length', 0)

    cy.get('[data-cy="usuario-inativar"]').click()
    cy.get('[data-slot="confirm-dialog"]').contains('button', 'Inativar usuário').click()

    cy.wait('@atualizar').its('request.body').should('deep.equal', { ativo: false })
    cy.contains('Usuário inativado').should('be.visible')
  })
})

export {}
